<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('supervisor');$user=current_user();$flashes=render_flashes();$currentPage='notifications';$pageTitle='Notifications';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$nd=sv_notifications($conn,$uid,100);$notifications=$nd['items'];require __DIR__.'/_layout_start.php';?><div class="ux-page-header"><div><span class="ux-page-header__eyebrow">Notification Centre</span><h2>All Notifications</h2><p>Review recent alerts and updates for your Supervisor account.</p></div></div><div class="ux-card"><div class="ux-card__body"><?php if(!$notifications):?><div class="ux-empty"><div class="ux-empty__icon"><i class="fas fa-bell"></i></div><strong>No notifications</strong><span>New notifications will appear here.</span></div><?php else:foreach($notifications as $n):?><div class="ux-notification-item <?=(int)($n['is_read']??1)===0?'ux-notification-item--unread':''?>"><span class="ux-notification-item__icon"><i class="fas fa-bell"></i></span><div><strong><?=e((string)($n['title']??'Notification'))?></strong><span><?=e((string)($n['message']??''))?></span><?php if(!empty($n['created_at'])):?><span><?=e(date('d M Y, H:i',strtotime($n['created_at'])))?></span><?php endif;?></div></div><?php endforeach;endif;?></div></div><?php require __DIR__.'/_layout_end.php';?>